-- Controller BOMs, from 'Controllers_Data_Entry_(9_22_26).xlsx'
-- ============================================================
-- 5840 production BOMs - one per controller - and their 130,372 component lines.
--
-- RUN load_controllers_items_*.sql FIRST. Every parent and every component is matched by
-- ITEM NAME + BRAND + ITEM MODEL against the catalogue, and the script refuses to write
-- anything if even one of them is missing, listing what it could not find. Five components
-- also need fix_qerp_items_for_controllers_*.sql, which moves the QERP rows for
-- ANLY / OMR / WIX / MAC / CHS off 'No Brand'.
--
-- THE QUANTITY COLUMN. 4,096 of the 130,372 lines are wire and cable measured in metres -
-- 0.5, 1.5, 2.5, 3.5. tbl_setup_item_bom_details.bom_qty is an INTEGER column (bigint, and
-- uint in the Go model), so those quantities cannot be stored as they are. The script
-- checks the column's type and stops rather than silently truncating - 0.5 m would become
-- 0 m and the wire would vanish from 460 BOMs.
--
--   Either widen the column first, which is the honest fix and needs the API changed with it:
--       ALTER TABLE tbl_setup_item_bom_details ALTER COLUMN bom_qty decimal(18,4);
--       (then BomQty uint -> float64 in models/item_bom_details_model.go and
--        models/bom_view_item_list.go, and the BOM grids in inventory)
--
--   Or set @round_up_fractional_qty = 1 below, which rounds those lines UP to the next
--   whole unit - never down, so a BOM over-states the wire slightly instead of losing it.
--   A stop-gap for a database you cannot alter; the rounded lines are all listed.
--
-- WHAT IS NOT LOADED, because the schema has nowhere to put it:
--   * The per-line REMARKS (39,180 lines, 8 distinct texts such as 'Power', 'Control',
--     'Wye; alternative models'). They are carried in this script and written only if a
--     'remarks' column exists on tbl_setup_item_bom_details; otherwise they are counted and
--     reported. Nothing is lost from this file either way.
--   * The BOM Alternates sheet - substitute components, 24,580 rows. There is no table for
--     them anywhere in the schema, so they are not in this script at all. They need a
--     design decision first, not a migration.
--
-- Run again safely: a controller that already has a BOM is skipped and reported.
--
-- HOW TO RUN: sqlcmd -S <server> -d <database> -b -i <this file>  (or open it in SSMS).
-- With @commit = 0 everything is done and counted, then rolled back.

SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @commit bit = 0;                    -- 1 = keep the changes, 0 = trial run
DECLARE @round_up_fractional_qty bit = 0;   -- see THE QUANTITY COLUMN above

IF OBJECT_ID('tempdb..#parent') IS NOT NULL DROP TABLE #parent;
IF OBJECT_ID('tempdb..#comp')   IS NOT NULL DROP TABLE #comp;
IF OBJECT_ID('tempdb..#remark') IS NOT NULL DROP TABLE #remark;
IF OBJECT_ID('tempdb..#line')   IS NOT NULL DROP TABLE #line;
IF OBJECT_ID('tempdb..#bommap') IS NOT NULL DROP TABLE #bommap;
IF OBJECT_ID('tempdb..#bomall') IS NOT NULL DROP TABLE #bomall;

CREATE TABLE #parent (
    bom_no     int NOT NULL PRIMARY KEY,
    item_model nvarchar(400) NOT NULL,
    item_id    bigint NULL,
    existing   bit NOT NULL DEFAULT 0      -- 1 = this controller already has a BOM
);
CREATE TABLE #comp (
    comp_no    int NOT NULL PRIMARY KEY,
    name_code  nvarchar(50)  NOT NULL,
    brand_code nvarchar(50)  NOT NULL,
    item_model nvarchar(400) NOT NULL,
    item_id    bigint NULL
);
CREATE TABLE #remark (remark_no int NOT NULL PRIMARY KEY, text nvarchar(200) NOT NULL);
CREATE TABLE #line (
    bom_no    int NOT NULL,
    comp_no   int NOT NULL,
    qty       decimal(18,4) NOT NULL,
    remark_no int NOT NULL
);
CREATE TABLE #bommap (bom_no int PRIMARY KEY, bom_id bigint NOT NULL);  -- added by this run
CREATE TABLE #bomall (bom_no int PRIMARY KEY, bom_id bigint NOT NULL);  -- every BOM, new or not

-- The controllers ---------------------------------------------------------------













-- The components ----------------------------------------------------------------

-- The line remarks --------------------------------------------------------------

-- The lines ---------------------------------------------------------------------




































































































































-- Nothing is written until every row is matched ----------------------------------
UPDATE p
   SET p.item_id = i.id
  FROM #parent p
  JOIN tbl_setup_item i       ON i.item_model = p.item_model
  JOIN tbl_setup_item_name n  ON n.id = i.item_name_id  AND n.code = N'CTRL'
  JOIN tbl_setup_item_brand b ON b.id = i.item_brand_id AND b.code = N'NB';

UPDATE c
   SET c.item_id = i.id
  FROM #comp c
  JOIN tbl_setup_item i       ON i.item_model = c.item_model
  JOIN tbl_setup_item_name n  ON n.id = i.item_name_id  AND n.code = c.name_code
  JOIN tbl_setup_item_brand b ON b.id = i.item_brand_id AND b.code = c.brand_code;

IF EXISTS (SELECT 1 FROM #parent WHERE item_id IS NULL)
    OR EXISTS (SELECT 1 FROM #comp WHERE item_id IS NULL)
BEGIN
    SELECT 'controller not in the catalogue' AS problem, item_model
      FROM #parent WHERE item_id IS NULL ORDER BY item_model;
    SELECT 'component not in the catalogue' AS problem, name_code, brand_code, item_model
      FROM #comp WHERE item_id IS NULL ORDER BY name_code, brand_code, item_model;
    RAISERROR('Items are missing (listed above). Run load_controllers_items_*.sql, and fix_qerp_items_for_controllers_*.sql for the components, then run this again.', 16, 1);
    RETURN;
END

-- The quantity column has to be able to hold what the workbook says ---------------
DECLARE @qty_type sysname = (
    SELECT ty.name FROM sys.columns c
      JOIN sys.types ty ON ty.user_type_id = c.user_type_id
     WHERE c.object_id = OBJECT_ID(N'tbl_setup_item_bom_details') AND c.name = N'bom_qty');

DECLARE @fractional int = (SELECT COUNT(*) FROM #line WHERE qty <> FLOOR(qty));

IF @qty_type IN (N'int', N'bigint', N'smallint', N'tinyint')
   AND @fractional > 0 AND @round_up_fractional_qty = 0
BEGIN
    SELECT 'bom_qty is ' + @qty_type AS problem,
           @fractional AS lines_that_would_be_truncated,
           'widen the column (see the header) or set @round_up_fractional_qty = 1' AS choices;
    SELECT DISTINCT c.name_code, c.brand_code, c.item_model, l.qty, COUNT(*) OVER (PARTITION BY c.comp_no, l.qty) AS lines_
      FROM #line l JOIN #comp c ON c.comp_no = l.comp_no
     WHERE l.qty <> FLOOR(l.qty)
     ORDER BY c.item_model, l.qty;
    RAISERROR('bom_qty cannot hold the fractional quantities in this workbook - nothing was written.', 16, 1);
    RETURN;
END

BEGIN TRANSACTION;

-- A controller that already has a BOM is left exactly as it is.
UPDATE p SET p.existing = 1
  FROM #parent p WHERE EXISTS (SELECT 1 FROM tbl_setup_item_bom b WHERE b.item_id = p.item_id);

-- 1. The BOM headers --------------------------------------------------------------
MERGE tbl_setup_item_bom AS t
USING (SELECT bom_no, item_id FROM #parent WHERE existing = 0) AS x
ON 1 = 0
WHEN NOT MATCHED THEN
    INSERT (item_id, production_qty, production_type, man_days, labor_rate, production_cost)
    VALUES (x.item_id, 1, N'PRODUCTION', 0, 0, 0)
OUTPUT inserted.id, x.bom_no INTO #bommap (bom_id, bom_no);

-- Every controller's BOM, whether this run created it or an earlier one did. The remarks
-- step below works off this, so running the script again after adding the remarks column
-- fills in the BOMs that are already loaded instead of skipping them.
SELECT p.bom_no, b.id
  FROM #parent p
  JOIN tbl_setup_item_bom b ON b.item_id = p.item_id;

-- 2. The component lines ----------------------------------------------------------
-- unit_price and net_price are left at 0: the workbook carries no prices, and the BOM
-- screen fills them from the item when it is priced.
SELECT m.bom_id,
       c.item_id,
       CASE WHEN @round_up_fractional_qty = 1 THEN CEILING(l.qty) ELSE l.qty END,
       0, 0
  FROM #line l
  JOIN #bommap m ON m.bom_no = l.bom_no
  JOIN #comp   c ON c.comp_no = l.comp_no;

-- 3. The line remarks, if this database has somewhere to put them ------------------
DECLARE @remarks_written int = 0;
IF COL_LENGTH(N'tbl_setup_item_bom_details', N'remarks') IS NOT NULL
BEGIN
    DECLARE @sql nvarchar(max) = N'
        UPDATE d
           SET d.remarks = r.text
          FROM tbl_setup_item_bom_details d
          JOIN #bomall m ON m.bom_id = d.item_bom_id
          JOIN #comp   c ON c.item_id = d.item_id
          JOIN #line   l ON l.bom_no = m.bom_no AND l.comp_no = c.comp_no
          JOIN #remark r ON r.remark_no = l.remark_no;
        SELECT @out = @@ROWCOUNT;';
    EXEC sp_executesql @sql, N'@out int OUTPUT', @out = @remarks_written OUTPUT;
END

-- What happened -------------------------------------------------------------------
SELECT (SELECT COUNT(*) FROM #parent)                    AS controllers_in_workbook,
       (SELECT COUNT(*) FROM #bommap)                    AS boms_added,
       (SELECT COUNT(*) FROM #parent WHERE existing = 1)  AS already_had_a_bom,
       (SELECT COUNT(*) FROM #line l JOIN #bommap m ON m.bom_no = l.bom_no) AS component_lines_added,
       @fractional                                        AS fractional_qty_lines,
       CASE WHEN @round_up_fractional_qty = 1 THEN 'rounded up' ELSE 'stored as given' END AS fractional_qty_handling,
       @qty_type                                          AS bom_qty_column_type,
       (SELECT COUNT(*) FROM #line WHERE remark_no > 0)   AS lines_with_a_remark,
       @remarks_written                                   AS remarks_written;

IF @round_up_fractional_qty = 1 AND @fractional > 0
    SELECT DISTINCT 'rounded up' AS note, c.name_code, c.brand_code, c.item_model,
           l.qty AS workbook_qty, CEILING(l.qty) AS stored_qty
      FROM #line l JOIN #comp c ON c.comp_no = l.comp_no
     WHERE l.qty <> FLOOR(l.qty)
     ORDER BY c.item_model, l.qty;

IF @remarks_written = 0 AND EXISTS (SELECT 1 FROM #line WHERE remark_no > 0)
    SELECT 'not stored - tbl_setup_item_bom_details has no remarks column' AS note,
           r.text, COUNT(*) AS lines_
      FROM #line l JOIN #remark r ON r.remark_no = l.remark_no
     GROUP BY r.text ORDER BY COUNT(*) DESC;

SELECT 'already had a BOM, left alone' AS state, item_model, item_id
  FROM #parent WHERE existing = 1 ORDER BY item_model;

IF @commit = 1
BEGIN
    COMMIT TRANSACTION;
    PRINT 'committed';
END
ELSE
BEGIN
    ROLLBACK TRANSACTION;
    PRINT 'rolled back - set @commit = 1 to write';
END

IF OBJECT_ID('tempdb..#parent') IS NOT NULL DROP TABLE #parent;
IF OBJECT_ID('tempdb..#comp')   IS NOT NULL DROP TABLE #comp;
IF OBJECT_ID('tempdb..#remark') IS NOT NULL DROP TABLE #remark;
IF OBJECT_ID('tempdb..#line')   IS NOT NULL DROP TABLE #line;
IF OBJECT_ID('tempdb..#bommap') IS NOT NULL DROP TABLE #bommap;
IF OBJECT_ID('tempdb..#bomall') IS NOT NULL DROP TABLE #bomall;
